"""One item's work on a backend resource of its own, and the state a batch shares."""

import asyncio


class Batch:
    """The shared state of one batch: its items, results, first failure and running works."""

    def __init__(self, items, backend):
        self.items = list(items)
        self.backend = backend
        self.results = [None] * len(self.items)
        self.position = 0
        self.failure = None
        self.works = set()

    def fail(self, exc):
        """Keeps exc when it is the first failure and cancels every running work."""
        if self.failure is None:
            self.failure = exc
        for work in list(self.works):
            work.cancel()


async def guarded(batch, item, token):
    """The item's work; a failure stops the other works at once."""
    try:
        return await batch.backend.process(item, token)
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        batch.works.discard(asyncio.current_task())
        batch.fail(exc)
        raise


async def labour(batch, index):
    """Acquires a resource for one item, does its work unless the batch has
    failed, and always hands the resource back with an awaited release."""
    item = batch.items[index]
    backend = batch.backend
    try:
        token = await backend.acquire(item)
    except Exception as exc:
        batch.fail(exc)
        return
    try:
        if batch.failure is None:
            work = asyncio.create_task(guarded(batch, item, token))
            batch.works.add(work)
            try:
                await asyncio.wait({work})
            finally:
                batch.works.discard(work)
            if not work.cancelled():
                exc = work.exception()
                if exc is not None:
                    batch.fail(exc)
                elif batch.failure is None:
                    batch.results[index] = work.result()
    finally:
        await backend.release(token)


async def drive(batch):
    """One of the two lanes: takes the next item until none is left or the batch failed."""
    while batch.failure is None and batch.position < len(batch.items):
        index = batch.position
        batch.position += 1
        await labour(batch, index)


async def outlast(batch, tasks):
    """Waits until every task has ended; the caller's cancellation is recorded
    as a failure and stops the works, but never cuts the wait short."""
    pending = set(tasks)
    while pending:
        try:
            await asyncio.wait(pending)
        except asyncio.CancelledError as exc:
            batch.fail(exc)
        pending = {task for task in pending if not task.done()}
    for task in tasks:
        if not task.cancelled() and task.exception() is not None:
            batch.fail(task.exception())

"""The backend's lifecycle around a batch."""

import asyncio


async def stop_backend(batch):
    """Shuts the backend down once, after everything else, and settles what
    the caller sees: the first failure, else close's own error, else the results."""
    closing = asyncio.create_task(batch.backend.close())
    while not closing.done():
        try:
            await asyncio.wait({closing})
        except asyncio.CancelledError as exc:
            batch.fail(exc)
    close_error = None
    if not closing.cancelled():
        close_error = closing.exception()
    if batch.failure is not None:
        raise batch.failure
    if close_error is not None:
        raise close_error
    return list(batch.results)
